import sys
from collections import Counter

def main():
    import sys
    import collections

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, q = read_ints()
    coins = read_ints()
    queries = [int(sys.stdin.readline()) for _ in range(q)]

    # Count the occurrences of each power of 2 in the coins
    coin_counts = Counter(collections.Counter(coins).elements())

    # Precompute the maximum power of 2 we can form
    max_power = sum(coin_counts[pow(2, i)] * pow(2, i) for i in range(30))

    results = []

    for b in queries:
        if b > max_power:
            results.append(-1)
            continue

        # Check if we can form the value b
        current_value = 0
        used_coins = 0
        for i in range(29, -1, -1):
            bit = (b >> i) & 1
            if bit == 1:
                if coin_counts[pow(2, i)] > 0:
                    coin_counts[pow(2, i)] -= 1
                    used_coins += 1
                    current_value += pow(2, i)
                else:
                    break

        if current_value == b:
            results.append(used_coins)
        else:
            results.append(-1)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
